-- Bộ đệm "Lấy thông tin thông minh": kết quả tra một IMO ở nguồn ngoài. Một dòng cho một IMO và một nguồn.
-- fetched_at cũng là mốc thời gian chờ: trong thời gian chờ thì trả lại bản đã lưu, không gọi nguồn ngoài.
-- Chỉ lưu lần gọi nguồn đã trả lời (có tàu hoặc không có tàu). Lỗi mạng không lưu nên không tính vào thời gian chờ.
CREATE TABLE "vessel_lookup" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "imo_number" varchar(7) NOT NULL,
  "provider" varchar(30) NOT NULL,
  "status" varchar(20) NOT NULL CHECK ("status" IN ('FOUND', 'NOT_FOUND')),
  "raw" JSONB,
  "fetched_by" INTEGER,
  "fetched_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE UNIQUE INDEX "vessel_lookup_uq_imo_provider" ON "vessel_lookup" ("imo_number", "provider");
